/**
 * FCLaranang Construction QA/QC System
 * Excel Template Engine & Loader for FCL_BOQ_Template.xlsx
 */

const FCL_BOQ_TEMPLATE_BASE64 = '';

async function getFclTemplateArrayBuffer() {
  // 1. Attempt live fetch from disk (reflects any user updates in templates/ folder)
  if (typeof fetch !== 'undefined') {
    try {
      const res = await fetch('templates/FCL_BOQ_Template.xlsx');
      if (res.ok) {
        return await res.arrayBuffer();
      }
    } catch (e) {
      console.warn('Live template fetch skipped (likely file:/// protocol), using embedded template buffer:', e.message);
    }
  }

  // 2. Attempt Node.js fs if in test environment
  if (typeof require !== 'undefined') {
    try {
      const fs = require('fs');
      const path = require('path');
      const p = path.join(__dirname, 'templates', 'FCL_BOQ_Template.xlsx');
      if (fs.existsSync(p)) {
        const fileBuf = fs.readFileSync(p);
        return fileBuf.buffer.slice(fileBuf.byteOffset, fileBuf.byteOffset + fileBuf.byteLength);
      }
    } catch (e) {}
  }

  // 3. Fallback to in-memory Base64 template
  try {
    if (typeof atob !== 'undefined') {
      const binary = atob(FCL_BOQ_TEMPLATE_BASE64);
      const len = binary.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binary.charCodeAt(i);
      }
      return bytes.buffer;
    } else if (typeof Buffer !== 'undefined') {
      const b = Buffer.from(FCL_BOQ_TEMPLATE_BASE64, 'base64');
      return b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength);
    }
  } catch (e) {
    console.error('Failed to decode template base64:', e);
  }

  return null;
}

if (typeof window !== 'undefined') {
  window.getFclTemplateArrayBuffer = getFclTemplateArrayBuffer;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { getFclTemplateArrayBuffer, FCL_BOQ_TEMPLATE_BASE64 };
}
